import {readFile,writeFile} from 'node:fs/promises';
import {fileURLToPath} from 'node:url';
import path from 'node:path';
import demo from './demo-build.cjs';
const root=path.dirname(fileURLToPath(import.meta.url));
const read=relative=>readFile(path.join(root,relative),'utf8');
const escapeScript=source=>source.replace(/<\/script/gi,'<\\/script');
const paths={STARTUP:'src/startup.js',CONFIG:'source-register.json',ENGINE:'src/engine.js',FIELD:'src/refined-field.js',SCALAR:'src/refined-scalar.js',MATRIX:'src/gfm-matrix.js',EXACT:'src/gfm-exact.js',MODELS:'src/gfm-models.js',REGISTRY:'equation-audit.json',IMAGES:'image-equations.json',REAPPLICATION:'gfm-reapplication.json',HORIZONGR:'src/horizon-gr.js',SCENARIO:'src/horizon-scenario.js',HORIZON:'src/horizon-models.js',HORIZONREGISTRY:'horizon-equations.json',HORIZONDATA:'horizon-reapplication.json',MECHANICS:'src/gfm-mechanics.js',APP:'src/app.js'};
const globals={CONFIG:'RusslConfig',REGISTRY:'RusslEquationRegistry',IMAGES:'RusslImageRegistry',REAPPLICATION:'RusslReapplication',HORIZONREGISTRY:'RusslHorizonRegistry',HORIZONDATA:'RusslHorizonData'};
const [template,...values]=await Promise.all([read('src/template.html'),...Object.values(paths).map(read)]);
const styles=await Promise.all(['src/styles.css','src/audit-styles.css','src/gfm-styles.css','src/horizon-styles.css','src/mechanics-styles.css'].map(read));
demo.build();
let generated=template.replace('/*__STYLE__*/',()=>styles.join('\n')).replace('/*__DEMO__*/',()=>demo.markup());
Object.keys(paths).forEach((name,i)=>{const content=globals[name]?'globalThis.'+globals[name]+'='+values[i]+';':values[i];generated=generated.replace('/*__'+name+'__*/',()=>escapeScript(content));});
if(/\/\*__[A-Z]+__\*\//.test(generated))throw Error('Unfilled build placeholder.');
await writeFile(path.join(root,'index.html'),generated);
const [bridge,workbench]=await Promise.all(['src/workbench-bridge.js','reference/workbench-original.html'].map(read));
const body=workbench.lastIndexOf('</body>');
if(body<0)throw new Error('Original workbench closing body tag missing.');
const derivative=workbench.slice(0,body)+'\n<!-- Virtual-terminal bridge added 2026-10-11; original source retained separately. -->\n<script>'+escapeScript(bridge)+'</script>\n'+workbench.slice(body);
await writeFile(path.join(root,'reference/workbench.html'),derivative);
console.log('Built GFM v0.5.1 with visible readiness and a calculated, script-free example.');
